/* Invented-only contract demonstration. No provider, source writer, disk state or private configuration. */
import http from 'node:http';
import {pathToFileURL} from 'node:url';
import {prepareConversationTranslation,runConversationTranslation} from '../../public/document-study/conversation-translation-bridge.js';
import {makeChatGPTBatch,mergeChatGPTBatch} from '../../runtime/services/magazine/chatgpt-translation.mjs';
export const inventedConversation=()=>({revision:9,session:{id:'invented-garden',title:'An invented garden conversation',sourceId:'11111111-1111-4111-8111-111111111111',sourceHash:'a'.repeat(64),version:4,undoOperationId:'invented-human-undo',turns:[
{id:'garden',speaker:'Chinese side',language:'zh',originalText:'虚构的花园很安静。',text:'虚构的花园很安静。',timestamp:'09:01'},
{id:'edited',speaker:'Named guest',language:'zh',originalText:'虚构的旧话。',text:'My carefully edited English.',corrections:[{id:'invented-human-edit'}]},
{id:'english',speaker:'English side',language:'zh',originalText:'An English aside.',text:'An English aside.'},
{id:'number',speaker:'Chinese side',language:'zh',originalText:'123',text:'123'},
{id:'boundary',kind:'session-boundary',speaker:'Editor',originalText:'Invented second session',text:'Invented second session',timestamp:'10:00'},
{id:'river',speaker:'Chinese side',language:'zh',originalText:'虚构的河流在附近。',text:'虚构的河流在附近。',timestamp:'10:02'}]}});
const contracts={makePacket:makeChatGPTBatch,validateTranslation:mergeChatGPTBatch};
export async function simulateConversationTranslation(mode='success'){
  if(!['success','stale','error','unavailable'].includes(mode))throw Error('Choose an invented demonstration mode.');
  const initial=inventedConversation(),before=JSON.stringify(initial),stale=structuredClone(initial);stale.revision++;stale.session.turns[1].text='A newer invented human edit.';let calls=0;
  const result=await runConversationTranslation({...contracts,readCurrent:async()=>mode==='stale'&&calls?stale:initial,permission:mode==='unavailable'?undefined:{execution:true,shareContext:true},execute:async packet=>{
    calls++;if(mode==='error')throw Error('Invented executor failure. No model ran.');
    return {recordingId:packet.recordingId,sourceDigest:packet.sourceDigest,language:packet.language,batch:packet.batch,segments:packet.segments.map((s,index)=>({id:s.id,text:['The invented garden is quiet.','The invented river is nearby.'][index],uncertainty:''}))};
  }});
  return {fixture:true,executor:'canned invented answers; no inference',calls,result,sourceUnchanged:JSON.stringify(initial)===before,session:initial.session};
}
const page=`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Invented conversation translation</title><style>
*{box-sizing:border-box}body{margin:0;background:#f7f7f3;color:#242923;font:16px/1.6 system-ui,sans-serif}main{max-width:850px;margin:auto;padding:24px}h1{font-size:25px;line-height:1.25;margin:0 0 8px}p{margin:8px 0}button{font:inherit;color:inherit;background:white;border:1px solid #b8c0b7;border-radius:5px;padding:7px 12px;min-height:40px;cursor:pointer}button:disabled{opacity:.5}nav{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0 12px}.quiet,small{color:#5c685a;font-size:14px}article{border-top:1px solid #cbd1c7;margin-top:20px;padding-top:12px}.remark{margin:0 0 14px}.remark small{display:block;font-size:12px}.remark p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.boundary{border-top:1px solid #cbd1c7;padding-top:10px}details{margin-top:18px}pre{font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}a{color:#285143}#state{font-weight:600}#preservation{font-size:14px} @media(max-width:500px){main{padding:18px}h1{font-size:22px}nav button{flex:1 1 140px}}
</style><main><h1>One conversation, only the translation gaps</h1><p class="quiet">Invented demonstration. Canned answers pass through the maintained translation validator. No model runs and no source words are saved.</p><nav aria-label="Invented outcomes"><button data-mode="success">Preview fixture proposals</button><button data-mode="stale">Try changed source</button><button data-mode="error">Try executor error</button><button data-mode="unavailable">Show execution gate</button></nav><p id="state" role="status">Two Chinese remarks need English. Every remark is visible.</p><p id="preservation"></p><article aria-label="Invented conversation"><div id="conversation"></div></article><details><summary>Prepared context and turn mapping</summary><pre id="packet"></pre></details><details><summary>Real execution remains unconnected</summary><p>The integrated reader still prepares translation gaps only. The maintained automatic route needs its configured Codex executable, signed-in account and explicit permission to send the conversation as context. A source-owner connection must reread the exact source revision and present proposals through the existing correction path. This demonstration provides none of those permissions or writes.</p></details></main><script type="module">
let session;const q=s=>document.querySelector(s);function show(proposals=[]){const texts=new Map(proposals.map(p=>[p.turnId,p.text]));q('#conversation').replaceChildren(...session.turns.map(t=>{const row=document.createElement('div');row.className='remark'+(t.kind==='session-boundary'?' boundary':'');const label=document.createElement('small');label.textContent=t.speaker+(t.timestamp?' · '+t.timestamp:'');const words=document.createElement('p');words.dataset.turn=t.id;words.textContent=texts.get(t.id)||t.text;row.append(label,words);return row;}));}
const initial=await(await fetch('/fixture')).json();session=initial.session;show();q('#packet').textContent=JSON.stringify(initial.prepared,null,2);
for(const button of document.querySelectorAll('[data-mode]'))button.addEventListener('click',async()=>{for(const b of document.querySelectorAll('button'))b.disabled=true;q('#state').textContent='Checking the invented conversation…';try{const receipt=await(await fetch('/simulate/'+button.dataset.mode)).json();const r=receipt.result;show(r.proposals);q('#state').textContent=r.state==='proposal-ready'?'Fixture proposals only · not applied':r.message;q('#state').dataset.state=r.state;q('#preservation').textContent=(receipt.sourceUnchanged?'Saved source, human edit, originals, IDs, timestamps and Undo remain unchanged.':'Fixture source comparison failed.')+' Canned executor calls: '+receipt.calls+'.';}catch{q('#state').textContent='The invented demonstration could not be loaded.';}finally{for(const b of document.querySelectorAll('button'))b.disabled=false;}});
</script></html>`;
export function startSyntheticTranslationDemo(port=59979){const server=http.createServer(async(req,res)=>{res.setHeader('Cache-Control','no-store');try{const pathname=new URL(req.url,'http://127.0.0.1').pathname;if(req.method!=='GET'){res.writeHead(405);return res.end();}if(pathname==='/'){res.setHeader('Content-Type','text/html; charset=utf-8');return res.end(page);}let value;if(pathname==='/fixture'){const initial=inventedConversation(),p=prepareConversationTranslation({...initial,...contracts});value={fixture:true,session:initial.session,prepared:{mapping:p.mapping,packets:p.packets}};}else if(pathname.startsWith('/simulate/'))value=await simulateConversationTranslation(pathname.slice('/simulate/'.length));else{res.writeHead(404);return res.end();}res.setHeader('Content-Type','application/json');res.end(JSON.stringify(value));}catch(error){res.writeHead(400,{'Content-Type':'application/json'});res.end(JSON.stringify({error:error.message}));}});return server.listen(port,'127.0.0.1');}
if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){const port=Number(process.env.AR_CREATE_BRIDGE_DEMO_PORT||59979);startSyntheticTranslationDemo(port);console.log('Invented translation bridge only: http://127.0.0.1:'+port+'/');}
